INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Band Skull Crusher with a resistance band. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.", "1": "The same phase of the movement continues smoothly.", "2": "Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "The same phase of the movement continues smoothly.", "5": "Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'band-skull-crusher';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Barbell Ab Rollout with a loaded barbell, frozen at the moment described as: "While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs" — textbook exercise form, the pose clearly recognisable as Barbell Ab Rollout, sharp focus on body position', false FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Barbell Ab Rollout with a loaded barbell, frozen at the moment described as: "After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale" — textbook exercise form, the pose clearly recognisable as Barbell Ab Rollout, sharp focus on body position', false FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Barbell Ab Rollout with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.", "3": "The same phase of the movement continues smoothly.", "4": "After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.", "5": "Repeat for the recommended amount of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'barbell-ab-rollout';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Barbell Ab Rollout - On Knees with a loaded barbell, frozen at the moment described as: "Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position" — textbook exercise form, the pose clearly recognisable as Barbell Ab Rollout - On Knees, sharp focus on body position', false FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Barbell Ab Rollout - On Knees with a loaded barbell, frozen at the moment described as: "Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement" — textbook exercise form, the pose clearly recognisable as Barbell Ab Rollout - On Knees, sharp focus on body position', false FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Barbell Ab Rollout - On Knees with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.", "1": "The same phase of the movement continues smoothly.", "2": "Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.", "5": "After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'barbell-ab-rollout-on-knees';
