INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Barbell Bench Press - Medium Grip with a loaded barbell, frozen at the moment described as: "Repeat the movement for the prescribed amount of repetitions" — textbook exercise form, the pose clearly recognisable as Barbell Bench Press - Medium Grip, sharp focus on body position', false FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Barbell Bench Press - Medium Grip with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "1": "From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.", "2": "The same phase of the movement continues smoothly.", "3": "After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.", "4": "Repeat the movement for the prescribed amount of repetitions.", "5": "The same phase of the movement continues smoothly.", "6": "When you are done, place the bar back in the rack.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'barbell-bench-press-medium-grip';
