INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Barbell Rollout from Bench with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.", "3": "The same phase of the movement continues smoothly.", "4": "The same phase of the movement continues smoothly.", "5": "When the bar has been moved as far forward as possible, return to the starting position.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'barbell-rollout-from-bench';
