INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Barbell Shrug Behind The Back with a loaded barbell. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.", "3": "The same phase of the movement continues smoothly.", "4": "Slowly return to the starting position as you breathe in.", "5": "Repeat for the recommended amount of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'barbell-shrug-behind-the-back';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Barbell Side Bend with a loaded barbell, frozen at the moment described as: "While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary" — textbook exercise form, the pose clearly recognisable as Barbell Side Bend, sharp focus on body position', false FROM exercise WHERE slug = 'barbell-side-bend';
