INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Barbell Walking Lunge with a loaded barbell. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Begin standing with your feet shoulder width apart and a barbell across your upper back.", "1": "The same phase of the movement continues smoothly.", "2": "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "3": "The same phase of the movement continues smoothly.", "4": "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "5": "Step forward with your rear foot, repeating the lunge on the opposite leg.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'barbell-walking-lunge';
