INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Bench Jump, bodyweight only, no equipment. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.", "1": "Perform a short squat in preparation for the jump; swing your arms behind you.", "2": "The same phase of the movement continues smoothly.", "3": "Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.", "4": "Jump over the bench, landing with the knees bent, absorbing the impact through the legs.", "5": "The same phase of the movement continues smoothly.", "6": "Turn around and face the opposite direction, then jump back over the bench.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'bench-jump';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Bench Press - Powerlifting with a loaded barbell, frozen at the moment described as: "However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart" — textbook exercise form, the pose clearly recognisable as Bench Press - Powerlifting, sharp focus on body position', false FROM exercise WHERE slug = 'bench-press-powerlifting';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Bench Press - Powerlifting with a loaded barbell, frozen at the moment described as: "Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times" — textbook exercise form, the pose clearly recognisable as Bench Press - Powerlifting, sharp focus on body position', false FROM exercise WHERE slug = 'bench-press-powerlifting';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Bench Press - Powerlifting with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.", "1": "The same phase of the movement continues smoothly.", "2": "However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.", "3": "The same phase of the movement continues smoothly.", "4": "Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.", "5": "Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'bench-press-powerlifting';
