INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Bench Press - With Bands with a resistance band. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Using a flat bench secure a band under the leg of the bench that is nearest to your head.", "1": "Once the band is secure, grab it by both handles and lie down on the bench.", "2": "Extend your arms so that you are holding the band handles in front of you at shoulder width.", "3": "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "4": "Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.", "5": "As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.", "6": "Repeat the movement for the prescribed amount of repetitions of your training program.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'bench-press-with-bands';
