INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Bent-Arm Barbell Pullover with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie on a flat bench with a barbell using a shoulder grip width.", "1": "Hold the bar straight over your chest with a bend in your arms. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.", "4": "At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.", "5": "The same phase of the movement continues smoothly.", "6": "Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'bent-arm-barbell-pullover';
