INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Cable Hip Adduction at a cable machine. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.", "1": "Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.", "2": "Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.", "3": "Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.", "4": "Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.", "5": "Slowly return to the starting position as you breathe in.", "6": "Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'cable-hip-adduction';
