INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Cable Iron Cross at a cable machine. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.", "1": "Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a \"T\". This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Keeping the elbows extended, pull your arms straight to your sides.", "4": "Return your arms back to the starting position after a pause at the peak contraction.", "5": "The same phase of the movement continues smoothly.", "6": "Continue the movement for the prescribed number of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'cable-iron-cross';
