INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Cable Wrist Curl at a cable machine. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.", "1": "Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.", "2": "Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.", "3": "The same phase of the movement continues smoothly.", "4": "Slowly lower your wrists back down to the starting position while inhaling.", "5": "Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'cable-wrist-curl';
