INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Close-Grip EZ-Bar Curl with Band with an EZ curl bar. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.", "1": "While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.", "2": "The same phase of the movement continues smoothly.", "3": "Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.", "4": "Slowly begin to bring the bar back to starting position as your breathe in.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'close-grip-ez-bar-curl-with-band';
