INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Close-Grip EZ-Bar Press with an EZ curl bar. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie on a flat bench with an EZ bar loaded to an appropriate weight.", "1": "Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.", "4": "Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'close-grip-ez-bar-press';
