INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Cross-Body Crunch, bodyweight only, no equipment, frozen at the moment described as: "Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee" — textbook exercise form, the pose clearly recognisable as Cross-Body Crunch, sharp focus on body position', false FROM exercise WHERE slug = 'cross-body-crunch';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Cross-Body Crunch, bodyweight only, no equipment. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie flat on your back and bend your knees about 60 degrees.", "1": "Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.", "4": "Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.", "5": "The same phase of the movement continues smoothly.", "6": "Continue alternating in this manner until all prescribed repetitions are done.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'cross-body-crunch';
