INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Cross Body Hammer Curl with dumbbells. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.", "1": "The same phase of the movement continues smoothly.", "2": "While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.", "3": "The same phase of the movement continues smoothly.", "4": "Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.", "5": "Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'cross-body-hammer-curl';
