INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'part_2', 'low side-on camera at floor level, full body in frame', '8-second video (part 2 of 2, to be stitched) of the athlete performing Decline Close-Grip Bench To Skull Crusher with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.", "1": "The same phase of the movement continues smoothly.", "2": "Lift the bar back to the starting position by contracting the triceps and exhaling.", "3": "The same phase of the movement continues smoothly.", "4": "The same phase of the movement continues smoothly.", "5": "Repeat steps 3-6 until the recommended amount of repetitions is performed.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'decline-close-grip-bench-to-skull-crusher';
