INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Decline Push-Up. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "3": "The same phase of the movement continues smoothly.", "4": "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "5": "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'decline-push-up';
