INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Dips - Triceps Version, bodyweight only, no equipment. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.", "1": "The same phase of the movement continues smoothly.", "2": "Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.", "3": "The same phase of the movement continues smoothly.", "4": "Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.", "5": "Repeat the movement for the prescribed amount of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'dips-triceps-version';
