INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Dumbbell Alternate Bicep Curl with dumbbells, frozen at the moment described as: "While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move" — textbook exercise form, the pose clearly recognisable as Dumbbell Alternate Bicep Curl, sharp focus on body position', false FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Dumbbell Alternate Bicep Curl with dumbbells, frozen at the moment described as: "Repeat the movement with the left hand. This equals one repetition" — textbook exercise form, the pose clearly recognisable as Dumbbell Alternate Bicep Curl, sharp focus on body position', false FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Dumbbell Alternate Bicep Curl with dumbbells. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.", "1": "While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.", "2": "The same phase of the movement continues smoothly.", "3": "Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.", "4": "Repeat the movement with the left hand. This equals one repetition.", "5": "The same phase of the movement continues smoothly.", "6": "Continue alternating in this manner for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'dumbbell-alternate-bicep-curl';
