INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Dumbbell Incline Row with dumbbells. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Using a neutral grip, lean into an incline bench.", "1": "The same phase of the movement continues smoothly.", "2": "Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "Retract the shoulder blades and flex the elbows to row the dumbbells to your side.", "5": "Pause at the top of the motion, and then return to the starting position.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'dumbbell-incline-row';
