INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Dumbbell Incline Shoulder Raise with dumbbells. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.", "1": "Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.", "4": "Bring back the dumbbells to the starting position as you breathe in.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'dumbbell-incline-shoulder-raise';
