INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Dumbbell Prone Incline Curl with dumbbells. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).", "1": "Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.", "2": "Now keep your elbows in by your side and face the palms forward. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.", "5": "Lower the dumbbells until your arms are fully extended.", "6": "Repeat for the recommended amount of times.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'dumbbell-prone-incline-curl';
