INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Elliptical Trainer on a gym machine. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.", "1": "The same phase of the movement continues smoothly.", "2": "The same phase of the movement continues smoothly.", "3": "The same phase of the movement continues smoothly.", "4": "The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.", "5": "The same phase of the movement continues smoothly.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'elliptical-trainer';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Exercise Ball Crunch with a large exercise ball, frozen at the moment described as: "Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position" — textbook exercise form, the pose clearly recognisable as Exercise Ball Crunch, sharp focus on body position', false FROM exercise WHERE slug = 'exercise-ball-crunch';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Exercise Ball Crunch with a large exercise ball, frozen at the moment described as: "As you inhale, go back to the starting position" — textbook exercise form, the pose clearly recognisable as Exercise Ball Crunch, sharp focus on body position', false FROM exercise WHERE slug = 'exercise-ball-crunch';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Exercise Ball Crunch with a large exercise ball. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).", "1": "Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.", "4": "As you inhale, go back to the starting position.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'exercise-ball-crunch';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Exercise Ball Pull-In with a large exercise ball, frozen at the moment described as: "Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position" — textbook exercise form, the pose clearly recognisable as Exercise Ball Pull-In, sharp focus on body position', false FROM exercise WHERE slug = 'exercise-ball-pull-in';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Exercise Ball Pull-In with a large exercise ball, frozen at the moment described as: "Now slowly straighten your legs, rolling the ball back to the starting position as you inhale" — textbook exercise form, the pose clearly recognisable as Exercise Ball Pull-In, sharp focus on body position', false FROM exercise WHERE slug = 'exercise-ball-pull-in';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Exercise Ball Pull-In with a large exercise ball. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.", "1": "Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.", "4": "Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'exercise-ball-pull-in';
