INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing External Rotation with Band with a resistance band. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.", "1": "Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.", "2": "The same phase of the movement continues smoothly.", "3": "With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.", "4": "Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.", "5": "The same phase of the movement continues smoothly.", "6": "Continue as far as you are able, pause, and then return to the starting position.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'external-rotation-with-band';
