INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Flat Bench Cable Flyes at a cable machine, frozen at the moment described as: "Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest" — textbook exercise form, the pose clearly recognisable as Flat Bench Cable Flyes, sharp focus on body position', false FROM exercise WHERE slug = 'flat-bench-cable-flyes';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Flat Bench Cable Flyes at a cable machine. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.", "1": "Lay flat on the bench and keep your feet on the ground.", "2": "Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.", "3": "Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.", "4": "Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.", "5": "Slowly come back to the starting position.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'flat-bench-cable-flyes';
