INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Frankenstein Squat with a loaded barbell, frozen at the moment described as: "Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves" — textbook exercise form, the pose clearly recognisable as Frankenstein Squat, sharp focus on body position', false FROM exercise WHERE slug = 'frankenstein-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Frankenstein Squat with a loaded barbell. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.", "1": "The same phase of the movement continues smoothly.", "2": "Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.", "3": "The same phase of the movement continues smoothly.", "4": "Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.", "5": "Return to the upright position by driving through the front of the heel and extending the knees and hips.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'frankenstein-squat';
