INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Freehand Jump Squat, bodyweight only, no equipment. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Cross your arms over your chest.", "1": "With your head up and your back straight, position your feet at shoulder width.", "2": "Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.", "3": "The same phase of the movement continues smoothly.", "4": "Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.", "5": "When you touch the floor again, immediately squat down and jump again.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'freehand-jump-squat';
