INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Front Cone Hops (or hurdle hops). side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Set up a row of cones or other small barriers, placing them a few feet apart.", "1": "Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Begin by jumping with both feet over the first cone, swinging both arms as you jump.", "4": "Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.", "5": "The same phase of the movement continues smoothly.", "6": "Continue until you have jumped over all of the cones.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'front-cone-hops-or-hurdle-hops';
