INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Hurdle Hops. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Set up a row of hurdles or other small barriers, placing them a few feet apart.", "1": "The same phase of the movement continues smoothly.", "2": "Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.", "5": "Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'hurdle-hops';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Hyperextensions (Back Extensions), frozen at the moment described as: "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms" — textbook exercise form, the pose clearly recognisable as Hyperextensions (Back Extensions), sharp focus on body position', false FROM exercise WHERE slug = 'hyperextensions-back-extensions';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Hyperextensions (Back Extensions), frozen at the moment described as: "Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury" — textbook exercise form, the pose clearly recognisable as Hyperextensions (Back Extensions), sharp focus on body position', false FROM exercise WHERE slug = 'hyperextensions-back-extensions';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Hyperextensions (Back Extensions). low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.", "1": "Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.", "2": "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.", "3": "The same phase of the movement continues smoothly.", "4": "Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.", "5": "Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'hyperextensions-back-extensions';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Hyperextensions With No Hyperextension Bench, bodyweight only, no equipment, frozen at the moment described as: "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms" — textbook exercise form, the pose clearly recognisable as Hyperextensions With No Hyperextension Bench, sharp focus on body position', false FROM exercise WHERE slug = 'hyperextensions-with-no-hyperextension-bench';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Hyperextensions With No Hyperextension Bench, bodyweight only, no equipment, frozen at the moment described as: "Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury" — textbook exercise form, the pose clearly recognisable as Hyperextensions With No Hyperextension Bench, sharp focus on body position', false FROM exercise WHERE slug = 'hyperextensions-with-no-hyperextension-bench';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Hyperextensions With No Hyperextension Bench, bodyweight only, no equipment. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.", "1": "With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.", "2": "The same phase of the movement continues smoothly.", "3": "Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.", "4": "Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'hyperextensions-with-no-hyperextension-bench';
