INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Iliotibial Tract-SMR with a foam roller. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.", "1": "The same phase of the movement continues smoothly.", "2": "Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.", "3": "The same phase of the movement continues smoothly.", "4": "The same phase of the movement continues smoothly.", "5": "Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'iliotibial-tract-smr';
