INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Inchworm, bodyweight only, no equipment. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.", "1": "Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.", "2": "The same phase of the movement continues smoothly.", "3": "Keep going until your body is parallel to the ground in a pushup position.", "4": "Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.", "5": "The same phase of the movement continues smoothly.", "6": "Continue walking until your feet are by hour hands, keeping your legs straight as you do so.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'inchworm';
