INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Incline Dumbbell Flyes - With A Twist with dumbbells. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.", "1": "Extend your arms above you with a slight bend at the elbows.", "2": "Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.", "5": "As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'incline-dumbbell-flyes-with-a-twist';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Incline Dumbbell Press with dumbbells, frozen at the moment described as: "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position" — textbook exercise form, the pose clearly recognisable as Incline Dumbbell Press, sharp focus on body position', false FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Incline Dumbbell Press with dumbbells, frozen at the moment described as: "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them" — textbook exercise form, the pose clearly recognisable as Incline Dumbbell Press, sharp focus on body position', false FROM exercise WHERE slug = 'incline-dumbbell-press';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Incline Dumbbell Press with dumbbells. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.", "1": "Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.", "2": "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "3": "Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.", "4": "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.", "5": "Repeat the movement for the prescribed amount of repetitions.", "6": "When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'incline-dumbbell-press';
