INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Isometric Wipers, bodyweight only, no equipment. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.", "3": "The same phase of the movement continues smoothly.", "4": "Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.", "5": "Repeat for the desired number of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'isometric-wipers';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing JM Press with a loaded barbell, frozen at the moment described as: "Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward" — textbook exercise form, the pose clearly recognisable as JM Press, sharp focus on body position', false FROM exercise WHERE slug = 'jm-press';
