INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Jackknife Sit-Up, bodyweight only, no equipment. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.", "3": "The same phase of the movement continues smoothly.", "4": "While inhaling, lower your arms and legs back to the starting position.", "5": "Repeat for the recommended amount of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'jackknife-sit-up';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Janda Sit-Up, bodyweight only, no equipment, frozen at the moment described as: "As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax" — textbook exercise form, the pose clearly recognisable as Janda Sit-Up, sharp focus on body position', false FROM exercise WHERE slug = 'janda-sit-up';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Janda Sit-Up, bodyweight only, no equipment, frozen at the moment described as: "As you inhale, slowly go back in a controlled manner to the starting position" — textbook exercise form, the pose clearly recognisable as Janda Sit-Up, sharp focus on body position', false FROM exercise WHERE slug = 'janda-sit-up';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Janda Sit-Up, bodyweight only, no equipment. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.", "3": "The same phase of the movement continues smoothly.", "4": "As you inhale, slowly go back in a controlled manner to the starting position.", "5": "Repeat for the recommended amount of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'janda-sit-up';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Jefferson Squats with a loaded barbell, frozen at the moment described as: "Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side" — textbook exercise form, the pose clearly recognisable as Jefferson Squats, sharp focus on body position', false FROM exercise WHERE slug = 'jefferson-squats';
