INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Linear 3-Part Start Technique. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.", "1": "The same phase of the movement continues smoothly.", "2": "Place your right hand onto the line, and thing bring your nose close to your left knee.", "3": "The same phase of the movement continues smoothly.", "4": "Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.", "5": "Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'linear-3-part-start-technique';
