INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Linear Acceleration Wall Drill. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.", "1": "The same phase of the movement continues smoothly.", "2": "Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.", "3": "The same phase of the movement continues smoothly.", "4": "Switch legs, raising the opposite knee, and then attacking the ground straight down.", "5": "Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'linear-acceleration-wall-drill';
