INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Moving Claw Series. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.", "1": "The same phase of the movement continues smoothly.", "2": "Reload the quad as the leg moves back forward, attacking the ground on the next step.", "3": "The same phase of the movement continues smoothly.", "4": "The same phase of the movement continues smoothly.", "5": "Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'moving-claw-series';
