INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing One-Arm Kettlebell Split Jerk with a cast-iron kettlebell. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.", "1": "Dip your body by bending the knees, keeping your torso upright.", "2": "The same phase of the movement continues smoothly.", "3": "Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.", "4": "Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.", "5": "The same phase of the movement continues smoothly.", "6": "Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'one-arm-kettlebell-split-jerk';
