INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing One Arm Dumbbell Preacher Curl with dumbbells. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.", "1": "As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.", "2": "The same phase of the movement continues smoothly.", "3": "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.", "4": "Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.", "5": "The same phase of the movement continues smoothly.", "6": "Switch arms and repeat the movement.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'one-arm-dumbbell-preacher-curl';
