INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Plyo Push-up, bodyweight only, no equipment. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Move into a prone position on the floor, supporting your weight on your hands and toes.", "1": "Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.", "2": "Descend by flexing at the elbow, lowering your chest towards the ground.", "3": "The same phase of the movement continues smoothly.", "4": "At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.", "5": "Return to the starting position and repeat the exercise.", "6": "For added difficulty, add claps into the movement while you are air borne.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'plyo-push-up';
