INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Posterior Tibialis Stretch. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "The same phase of the movement continues smoothly.", "3": "The same phase of the movement continues smoothly.", "4": "With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.", "5": "The same phase of the movement continues smoothly.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'posterior-tibialis-stretch';
