INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Power Stairs, frozen at the moment described as: "As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair" — textbook exercise form, the pose clearly recognisable as Power Stairs, sharp focus on body position', false FROM exercise WHERE slug = 'power-stairs';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Power Stairs. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.", "1": "The same phase of the movement continues smoothly.", "2": "Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.", "3": "The same phase of the movement continues smoothly.", "4": "As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18\" high. You can use your legs to help push the weight onto the stair.", "5": "Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'power-stairs';
