INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Reverse Barbell Preacher Curls with an EZ curl bar. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Grab an EZ-bar using a shoulder width and palms down (pronated) grip.", "1": "Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.", "4": "As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'reverse-barbell-preacher-curls';
