INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Ring Dips. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.", "1": "The same phase of the movement continues smoothly.", "2": "Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.", "3": "The same phase of the movement continues smoothly.", "4": "Reverse the motion by extending the elbow, pushing yourself back up into the starting position.", "5": "Repeat for the desired number of repetitions.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'ring-dips';
