INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Scissors Jump, bodyweight only, no equipment. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.", "1": "The same phase of the movement continues smoothly.", "2": "Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.", "3": "The same phase of the movement continues smoothly.", "4": "As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.", "5": "As you land, absorb the impact through the legs by adopting the lunge position, and repeat.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'scissors-jump';
