INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Seated Band Hamstring Curl. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Secure a band close to the ground and place a bench a couple feet away from it.", "1": "The same phase of the movement continues smoothly.", "2": "Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.", "5": "Pause at the completion of the movement, and then slowly return to the starting position.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'seated-band-hamstring-curl';
