INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Seated Barbell Military Press with a loaded barbell. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.", "1": "Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Lower the bar down to the collarbone slowly as you inhale.", "4": "Lift the bar back up to the starting position as you exhale.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'seated-barbell-military-press';
