INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Seated Two-Arm Palms-Up Low-Pulley Wrist Curl at a cable machine. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.", "1": "Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.", "2": "Now hold the handle with both hands, palms up, using a shoulder-width grip.", "3": "Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.", "4": "Lower the bar as far as possible, while inhaling and keeping a tight grip.", "5": "Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'seated-two-arm-palms-up-low-pulley-wrist-curl';
