INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Smith Machine Decline Press on a gym machine. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.", "1": "Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Begin the movement by flexing your arms, lowering the bar to your chest.", "4": "Pause briefly, and then extend your arms to push the weight back to the starting position.", "5": "The same phase of the movement continues smoothly.", "6": "After completing the desired number of repetitions, rotate the bar to rack the weight.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'smith-machine-decline-press';
