INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Smith Machine Pistol Squat on a gym machine, frozen at the moment described as: "Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows" — textbook exercise form, the pose clearly recognisable as Smith Machine Pistol Squat, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-pistol-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Smith Machine Pistol Squat on a gym machine. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.", "1": "Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3.", "2": "The same phase of the movement continues smoothly.", "3": "Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.", "4": "Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.", "5": "The same phase of the movement continues smoothly.", "6": "Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'smith-machine-pistol-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Smith Machine Reverse Calf Raises on a gym machine, frozen at the moment described as: "Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes" — textbook exercise form, the pose clearly recognisable as Smith Machine Reverse Calf Raises, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-reverse-calf-raises';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Smith Machine Reverse Calf Raises on a gym machine, frozen at the moment described as: "Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes" — textbook exercise form, the pose clearly recognisable as Smith Machine Reverse Calf Raises, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-reverse-calf-raises';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Smith Machine Reverse Calf Raises on a gym machine. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.", "1": "Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.", "2": "Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.", "3": "The same phase of the movement continues smoothly.", "4": "Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.", "5": "Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'smith-machine-reverse-calf-raises';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Smith Machine Squat on a gym machine, frozen at the moment described as: "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section)" — textbook exercise form, the pose clearly recognisable as Smith Machine Squat, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Smith Machine Squat on a gym machine, frozen at the moment described as: "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position" — textbook exercise form, the pose clearly recognisable as Smith Machine Squat, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Smith Machine Squat on a gym machine. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "1": "Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "2": "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "3": "The same phase of the movement continues smoothly.", "4": "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "5": "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'smith-machine-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Smith Machine Stiff-Legged Deadlift on a gym machine, frozen at the moment described as: "Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position" — textbook exercise form, the pose clearly recognisable as Smith Machine Stiff-Legged Deadlift, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-stiff-legged-deadlift';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Smith Machine Stiff-Legged Deadlift on a gym machine, frozen at the moment described as: "Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement" — textbook exercise form, the pose clearly recognisable as Smith Machine Stiff-Legged Deadlift, sharp focus on body position', false FROM exercise WHERE slug = 'smith-machine-stiff-legged-deadlift';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Smith Machine Stiff-Legged Deadlift on a gym machine. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.", "1": "Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement.", "4": "Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'smith-machine-stiff-legged-deadlift';
