INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Snatch Balance with a loaded barbell. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.", "1": "The same phase of the movement continues smoothly.", "2": "Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.", "3": "The same phase of the movement continues smoothly.", "4": "Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.", "5": "Continue to descend to full depth, and return to a standing position. Carefully lower the weight.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'snatch-balance';
