INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Snatch from Blocks with a loaded barbell, frozen at the moment described as: "Begin the first pull by driving through the front of the heels, raising the bar from the boxes" — textbook exercise form, the pose clearly recognisable as Snatch from Blocks, sharp focus on body position', false FROM exercise WHERE slug = 'snatch-from-blocks';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Snatch from Blocks with a loaded barbell, frozen at the moment described as: "As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead" — textbook exercise form, the pose clearly recognisable as Snatch from Blocks, sharp focus on body position', false FROM exercise WHERE slug = 'snatch-from-blocks';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Snatch from Blocks with a loaded barbell. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.", "1": "Begin the first pull by driving through the front of the heels, raising the bar from the boxes.", "2": "The same phase of the movement continues smoothly.", "3": "Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.", "4": "As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.", "5": "The same phase of the movement continues smoothly.", "6": "Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'snatch-from-blocks';
