INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Speed Band Overhead Triceps with a resistance band. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.", "1": "The same phase of the movement continues smoothly.", "2": "To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.", "5": "Pause, and then return to the starting position.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'speed-band-overhead-triceps';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Speed Box Squat with a loaded barbell, frozen at the moment described as: "Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max" — textbook exercise form, the pose clearly recognisable as Speed Box Squat, sharp focus on body position', false FROM exercise WHERE slug = 'speed-box-squat';
