INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Spell Caster with dumbbells. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.", "3": "The same phase of the movement continues smoothly.", "4": "Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.", "5": "Continue alternating, rotating from one side to the other until the set is complete.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'spell-caster';
