INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Squat with Bands with a loaded barbell, frozen at the moment described as: "With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee" — textbook exercise form, the pose clearly recognisable as Squat with Bands, sharp focus on body position', false FROM exercise WHERE slug = 'squat-with-bands';
