INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Standing Long Jump, bodyweight only, no equipment. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.", "1": "The same phase of the movement continues smoothly.", "2": "Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.", "3": "The same phase of the movement continues smoothly.", "4": "Attempt to land with your feet out in front you, reaching as far as possible with your legs.", "5": "Measure the distance from your landing point to the starting point and track results.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'standing-long-jump';
