INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Standing Low-Pulley Deltoid Raise at a cable machine. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.", "1": "Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.", "2": "Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.", "3": "The same phase of the movement continues smoothly.", "4": "Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.", "5": "Repeat for the recommended amount of repetitions.", "6": "Switch arms and repeat the exercise.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'standing-low-pulley-deltoid-raise';
