INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Standing Olympic Plate Hand Squeeze. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.", "3": "The same phase of the movement continues smoothly.", "4": "Now raise the plates back to the starting position as you exhale by closing your hands.", "5": "Repeat for the recommended amount of repetitions prescribed in your program.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'standing-olympic-plate-hand-squeeze';
