INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Stiff-Legged Dumbbell Deadlift with dumbbells. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Grasp a couple of dumbbells holding them by your side at arm''s length.", "1": "Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement.", "4": "Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'stiff-legged-dumbbell-deadlift';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Stiff Leg Barbell Good Morning with a loaded barbell, frozen at the moment described as: "Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position" — textbook exercise form, the pose clearly recognisable as Stiff Leg Barbell Good Morning, sharp focus on body position', false FROM exercise WHERE slug = 'stiff-leg-barbell-good-morning';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'side-on camera, full body in frame with headroom', 'full-body action photo of the athlete performing Stiff Leg Barbell Good Morning with a loaded barbell, frozen at the moment described as: "Begin to raise the bar as you exhale by elevating your torso back to the starting position" — textbook exercise form, the pose clearly recognisable as Stiff Leg Barbell Good Morning, sharp focus on body position', false FROM exercise WHERE slug = 'stiff-leg-barbell-good-morning';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Stiff Leg Barbell Good Morning with a loaded barbell. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "1": "Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "2": "Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.", "3": "The same phase of the movement continues smoothly.", "4": "Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.", "5": "Begin to raise the bar as you exhale by elevating your torso back to the starting position.", "6": "Repeat for the recommended amount of repetitions.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'stiff-leg-barbell-good-morning';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Stomach Vacuum, bodyweight only, no equipment, frozen at the moment described as: "Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone" — textbook exercise form, the pose clearly recognisable as Stomach Vacuum, sharp focus on body position', false FROM exercise WHERE slug = 'stomach-vacuum';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_b', 'three-quarter front camera, full body in frame', 'full-body action photo of the athlete performing Stomach Vacuum, bodyweight only, no equipment, frozen at the moment described as: "Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds" — textbook exercise form, the pose clearly recognisable as Stomach Vacuum, sharp focus on body position', false FROM exercise WHERE slug = 'stomach-vacuum';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Stomach Vacuum, bodyweight only, no equipment. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.", "1": "Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.", "2": "The same phase of the movement continues smoothly.", "3": "One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.", "4": "Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.", "5": "The same phase of the movement continues smoothly.", "6": "Repeat for the recommended amount of sets.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'stomach-vacuum';
