INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Vertical Swing with dumbbells. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.", "1": "The same phase of the movement continues smoothly.", "2": "Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.", "3": "The same phase of the movement continues smoothly.", "4": "Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.", "5": "As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'vertical-swing';
