INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'low side-on camera at floor level, full body in frame', '8-second seamless loopable video of the athlete performing Weighted Crunches with a medicine ball. low side-on camera at floor level, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.", "1": "Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.", "2": "The same phase of the movement continues smoothly.", "3": "Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.", "4": "At the top of the movement, flex your abdominals and hold for a brief pause.", "5": "The same phase of the movement continues smoothly.", "6": "Then inhale and slowly lower yourself back down to the starting position.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'weighted-crunches';
