INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'side-on camera, full body in frame with headroom', '8-second seamless loopable video of the athlete performing Weighted Sissy Squat with a loaded barbell. side-on camera, full body in frame with headroom. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.", "3": "The same phase of the movement continues smoothly.", "4": "After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.", "5": "Repeat for the recommended amount of times.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'weighted-sissy-squat';
INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, is_curated) SELECT id, 'image', 'pose_a', 'low side-on camera at floor level, full body in frame', 'full-body action photo of the athlete performing Weighted Sit-Ups - With Bands, frozen at the moment described as: "Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position" — textbook exercise form, the pose clearly recognisable as Weighted Sit-Ups - With Bands, sharp focus on body position', false FROM exercise WHERE slug = 'weighted-sit-ups-with-bands';
