INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'three-quarter front camera, full body in frame', '8-second seamless loopable video of the athlete performing Wrist Rotations with Straight Bar with a loaded barbell. three-quarter front camera, full body in frame. One continuous locked-off take, no cuts, no camera movement, steady natural rhythm; the final frame must match the first frame exactly so the clip loops.', '{"0": "Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.", "1": "The same phase of the movement continues smoothly.", "2": "Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.", "3": "The same phase of the movement continues smoothly.", "4": "The same phase of the movement continues smoothly.", "5": "Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.", "6": "The same phase of the movement continues smoothly.", "7": "She returns to the exact position and pose of second 0 so the clip loops seamlessly."}'::jsonb, false FROM exercise WHERE slug = 'wrist-rotations-with-straight-bar';
