INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'locked-off side-on camera, full body always in frame with headroom for the jump, no cuts, no camera movement', '8-second seamless loop: exactly two full burpee reps at a steady athletic pace, one rep every 4 seconds, ending in the identical standing position the clip starts in', '{"0": "She stands tall, feet shoulder-width apart, then crouches and plants both hands on the floor just inside her feet.", "1": "She jumps her feet back into a high plank and lowers her chest to the floor in one fluid push-up descent.", "2": "She presses powerfully back up to plank and snaps her feet forward to land just behind her hands.", "3": "She explodes upward into a vertical jump, arms sweeping straight overhead, then lands softly with bent knees back into standing.", "4": "Without pausing she crouches again and plants both hands on the floor, beginning the second identical rep.", "5": "Feet jump back to plank; chest lowers to the floor in the same smooth push-up.", "6": "She presses up and snaps her feet forward to her hands, loading the legs.", "7": "She jumps vertically with arms overhead and lands softly, finishing standing tall in exactly the same pose and position as frame one so the clip loops seamlessly."}'::jsonb, true FROM exercise WHERE slug = 'burpee';
