INSERT INTO exercise_media_prompt (exercise_id, target, variant, camera, prompt, beats, is_curated) SELECT id, 'video', 'loop_8s', 'locked-off straight-on front camera, full body in frame, perfectly centred, no cuts, no camera movement', '8-second seamless loop: exactly four full jumping jacks at a bright steady rhythm, one rep every 2 seconds, starting and ending feet-together with arms at her sides', '{"0": "From standing with feet together and arms at her sides, she jumps her feet out wide while her arms sweep overhead into a star shape.", "1": "She jumps her feet back together as her arms swing back down to her sides, landing lightly on the balls of her feet.", "2": "Second rep: feet jump out wide, arms sweep overhead, light and rhythmic.", "3": "Feet snap back together, arms return to her sides, posture tall.", "4": "Third rep: out wide with arms overhead, hair and body showing gentle bounce energy.", "5": "Back together, arms to sides, steady breathing rhythm.", "6": "Fourth rep: feet out wide, arms sweeping fully overhead one last time.", "7": "She lands back with feet together and arms at her sides in exactly the same pose as frame one so the clip loops seamlessly."}'::jsonb, true FROM exercise WHERE slug = 'jumping-jacks';
